extends SceneTree

func _init():
	var ev_key = InputEventKey.new()
	ev_key.keycode = KEY_ESCAPE
	var ev_joy = InputEventJoypadButton.new()
	ev_joy.button_index = 1

	print("Key: ", inst2dict(ev_key))
	print("Joy: ", inst2dict(ev_joy))

	# Let's also see what ProjectSettings saves
	ProjectSettings.set_setting("input/ui_back", {
		"deadzone": 0.5,
		"events": [ev_key, ev_joy]
	})
	ProjectSettings.save()
	quit()

