signal play_pressed
signal settings_pressed
signal quit_pressed

@onready var play_button: Button = $VBoxContainer/Play
@onready var settings_button: Button = $VBoxContainer/Settings
@onready var quit_button: Button = $VBoxContainer/Quit

func _ready():
	play_button.pressed.connect(_on_play_pressed)
	settings_button.pressed.connect(_on_settings_pressed)
	quit_button.pressed.connect(_on_quit_pressed)
	# Grab focus initially
	play_button.grab_focus()

func _on_play_pressed():
	play_pressed.emit()

func _on_settings_pressed():
	settings_pressed.emit()

func _on_quit_pressed():
	quit_pressed.emit()
	get_tree().quit()

extends Control

signal back_pressed

@onready var volume_slider: HSlider = $VBoxContainer/VolumeSlider
@onready var resolution_option: OptionButton = $VBoxContainer/ResolutionOption
@onready var fullscreen_check: CheckBox = $VBoxContainer/FullscreenCheck
@onready var back_button: Button = $VBoxContainer/BackButton

func _ready():
	# Load existing settings from GameSettings autoload
	volume_slider.value = GameSettings.volume

	# OptionButton needs exactly 3 items
	resolution_option.clear()
	resolution_option.add_item("1280x720")
	resolution_option.add_item("1920x1080")
	resolution_option.add_item("2560x1440")
	resolution_option.selected = GameSettings.resolution_index

	fullscreen_check.button_pressed = GameSettings.fullscreen

	# Connect signals to update GameSettings autoload
	volume_slider.value_changed.connect(_on_volume_changed)
	resolution_option.item_selected.connect(_on_resolution_selected)
	fullscreen_check.toggled.connect(_on_fullscreen_toggled)
	back_button.pressed.connect(_on_back_pressed)

func _process(_delta):
	if visible and Input.is_action_just_pressed("ui_back"):
		_on_back_pressed()

func _on_volume_changed(val: float):
	GameSettings.volume = val

func _on_resolution_selected(index: int):
	GameSettings.resolution_index = index

func _on_fullscreen_toggled(pressed: bool):
	GameSettings.fullscreen = pressed

func _on_back_pressed():
	# Hide ourselves and show MainMenu
	visible = false
	var main_menu = get_parent().get_node_or_null("MainMenu")
	if main_menu:
		main_menu.visible = true
		var settings_btn = main_menu.get_node_or_null("VBoxContainer/Settings")
		if settings_btn:
			settings_btn.grab_focus()
	back_pressed.emit()

extends Control

@onready var main_menu = $MainMenu
@onready var settings_menu = $SettingsMenu

func _ready():
	main_menu.visible = true
	settings_menu.visible = false

	# Connect signals
	main_menu.settings_pressed.connect(_on_settings_pressed)
	settings_menu.back_pressed.connect(_on_back_pressed)

func _on_settings_pressed():
	main_menu.visible = false
	settings_menu.visible = true
	# Grab focus on the first control of settings menu (volume slider)
	var volume_slider = settings_menu.get_node_or_null("VBoxContainer/VolumeSlider")
	if volume_slider:
		volume_slider.grab_focus()

func _on_back_pressed():
	settings_menu.visible = false
	main_menu.visible = true
	# Grab focus back on Settings button
	var settings_btn = main_menu.get_node_or_null("VBoxContainer/Settings")
	if settings_btn:
		settings_btn.grab_focus()

extends Control

